// pimpl.hpp에 실제로 사용하는 헤더 가드입니다.
#ifndef STUDY_PIMPL_HPP
#define STUDY_PIMPL_HPP
// 공개 선언을 이 번역 단위에 중복 포함하지 않도록 보호합니다.
#endif
// 다른 cpp에도 외부 변수 정의를 반복해도 된다는 뜻은 아닙니다.

// pimpl.hpp의 핵심 선언을 발췌했습니다.
class Settings {
    struct Impl;                   // 존재만 알립니다.
    std::unique_ptr<Impl> impl_;    // 별도 Impl을 소유합니다.
public:
    explicit Settings(std::string name);
    ~Settings();                   // 구현은 cpp에 둡니다.
    std::string Name() const;
    // 복사·이동·Rename 등의 전체 선언은 전체 소스에 있습니다.
};

// pimpl.cpp에서는 완전한 정의 뒤에 소멸자를 정의합니다.
struct Settings::Impl { std::string name; };
Settings::~Settings() = default;

// pimpl.cpp: 핸들을 복사하지 않고 새 Impl을 만듭니다.
Settings::Settings(const Settings& other)
    : impl_(other.impl_ ? std::make_unique<Impl>(*other.impl_) : nullptr) {}

Settings::Settings(Settings&&) noexcept = default;

std::string Settings::Name() const {
    if (!impl_) throw std::logic_error("empty moved-from settings");
    return impl_->name; // 참조가 아닌 소유 문자열 값을 반환합니다.
}

void Settings::Rename(std::string name) {
    auto candidate = std::make_unique<Impl>(Impl{std::move(name)});
    impl_.swap(candidate); // 준비가 끝난 뒤에만 소유 핸들을 교체합니다.
} // candidate가 이전 Impl을 정리합니다.

void swap(Settings& a, Settings& b) noexcept {
    a.impl_.swap(b.impl_); // 문자열을 복제하지 않고 포인터를 교환합니다.
}

// allocation.cpp: 추가 인수의 형식을 맞춘 한 쌍입니다.
static void* operator new(std::size_t bytes, Pool& source) {
    return source.Allocate(bytes);
}
static void operator delete(void* p, Pool& source) noexcept {
    source.Free(p);
}
// new(pool) Widget(pool, true)는 할당 뒤 생성자에서 예외를 던집니다.

struct ReturnToPool {
    Pool* pool; // Pool을 소유하지 않습니다.
    void operator()(Widget* p) const noexcept {
        if (p) {
            std::destroy_at(p); // 객체의 수명을 먼저 끝냅니다.
            pool->Free(p);      // 그다음 저장 공간을 반환합니다.
        }
    }
};

// allocation.cpp의 실제 소유자 구성입니다.
std::unique_ptr<Widget, ReturnToPool> owner(
    new(pool) Widget(pool, false), ReturnToPool{&pool});

// allocation.cpp: 자동 저장 공간은 bytes가 제공합니다.
alignas(int) std::array<std::byte, sizeof(int)> bytes{};
int* value = ::new(static_cast<void*>(bytes.data())) int(42);
// 전체 검사기는 *value == 42를 확인합니다.
std::destroy_at(value);
// delete value;를 호출하지 않습니다. 저장 공간은 자동 배열 소유입니다.

alignas(std::max_align_t) std::array<std::byte, 1024> arena{};
std::pmr::monotonic_buffer_resource resource(
    arena.data(), arena.size(), std::pmr::null_memory_resource());
{
    std::pmr::vector<int> values(&resource);
    values.reserve(8);  // 적어도 원소8개를 담을 용량을 요청합니다.
    values.push_back(7);
} // vector가 resource보다 먼저 정리됩니다.
// 전체 검사기에서 resource.allocate(4096)의 bad_alloc을 확인합니다.

#ifndef STUDY_PIMPL_HPP
#define STUDY_PIMPL_HPP
#include <memory>
#include <string>

// 공개 선언은 Impl의 존재만 알리고, 구체적인 데이터 배치는 pimpl.cpp로 숨긴다.
// 헤더 이용자가 Impl 정의 없이 Settings를 선언·사용하는 경계를 보여 준다.
// 이 예제만으로 배포 라이브러리의 ABI 호환성까지 검증한 것은 아니다.
class Settings {
    struct Impl;
    // unique_ptr 멤버의 선언에는 불완전 타입을 사용할 수 있다.
    // Impl의 삭제가 필요한 연산은 완전한 정의를 볼 수 있는 .cpp에 둔다.
    std::unique_ptr<Impl> impl_;
public:
    explicit Settings(std::string name);
    // 이 헤더 안에서 = default로 정의하지 않고, Impl 정의 뒤에서 정의한다.
    ~Settings();
    Settings(Settings&&) noexcept;
    Settings& operator=(Settings&&) noexcept;

    // 소유 핸들만 복사하지 않고 별도 Impl을 만드는 값 복사 계약이다.
    // unique_ptr 자체는 복사할 수 없으므로 구현에서 이 동작을 직접 정의한다.
    Settings(const Settings&);
    Settings& operator=(const Settings&);

    // 새 Impl을 준비한 뒤 교체한다. 비어 있는 이동 후 객체도 다시 채울 수 있다.
    void Rename(std::string name);
    // 내부 문자열의 참조나 뷰가 아니라 소유하는 std::string 값을 반환한다.
    // impl_가 없을 때는 logic_error를 던지는 계약을 구현에 둔다.
    std::string Name() const;
    bool Empty() const noexcept;
    // ADL로 찾는 비멤버 swap은 두 소유 핸들만 교환한다.
    friend void swap(Settings&, Settings&) noexcept;
};
#endif

#include "pimpl.hpp"
#include <stdexcept>
#include <utility>

// 실제 데이터 정의는 이 번역 단위에서만 보인다.
struct Settings::Impl { std::string name; };

Settings::Settings(std::string name) : impl_(std::make_unique<Impl>(Impl{std::move(name)})) {}

// 이 지점에서는 Impl이 완전하므로 unique_ptr의 삭제 동작을 구성할 수 있다.
Settings::~Settings() = default;
// 기본 이동은 unique_ptr의 소유권 이동이다. 정상적인 다른 객체로의 이동 뒤에는
// 원본 핸들이 비게 된다. 테스트는 이동 생성 경로를 실행한다.
Settings::Settings(Settings&&) noexcept = default;
Settings& Settings::operator=(Settings&&) noexcept = default;

// 원본이 차 있으면 별도 Impl과 문자열 값을 복사하고, 비었으면 비어 있게 복사한다.
// 현재 정상 테스트가 확인하는 것은 차 있는 원본을 복사한 뒤 각 이름을 바꾸는 경로다.
Settings::Settings(const Settings& other) : impl_(other.impl_ ? std::make_unique<Impl>(*other.impl_) : nullptr) {}

Settings& Settings::operator=(const Settings& other) {
    if (this != &other) {
        // 후보 복사가 실패하면 아직 *this를 변경하지 않았다.
        // 복사가 끝난 뒤 noexcept swap으로 교체하고, copy가 이전 상태를 정리한다.
        // 이 구조의 강한 예외 보장을 설명하되, 해당 테스트에서 할당 실패를 주입하지는 않는다.
        Settings copy(other);
        swap(*this, copy);
    }
    return *this;
}

void Settings::Rename(std::string name) {
    // 인자 준비와 후보 생성이 완료될 때까지 기존 impl_는 그대로다.
    auto candidate = std::make_unique<Impl>(Impl{std::move(name)});
    impl_.swap(candidate);
    // candidate가 이전 Impl을 소유한 채 범위를 벗어나 정리한다.
    // 파일·네트워크 부수 효과나 동시 접근을 다루는 트랜잭션은 아니다.
}

std::string Settings::Name() const {
    // 이동 후 비어 있는 상태를 유효한 상태로 인정하되, Name 접근은 명시적으로 거부한다.
    if (!impl_) throw std::logic_error("empty moved-from settings");
    // 값 복사 반환이므로 호출자는 Settings와 별도의 문자열 수명을 갖는다.
    return impl_->name;
}

bool Settings::Empty() const noexcept { return !impl_; }
// Impl의 문자열을 하나씩 교환하지 않고, 두 소유 포인터를 교환한다.
void swap(Settings& a, Settings& b) noexcept { a.impl_.swap(b.impl_); }

#include "check.hpp"
#include "pimpl.hpp"
#include <type_traits>

// 실행 시 검사 여섯 회와 별개인 컴파일 시점 성질 확인이다.
// 이 번역 단위는 Impl의 데이터 정의를 보지 않고 공개 헤더만 사용한다.
static_assert(std::is_nothrow_move_constructible_v<Settings>);

int main() { return Run("pimpl", [](Checks& c) {
    Settings a("old");
    Settings b = a;
    b.Rename("new");
    // 1. Rename 뒤 b의 새 이름과 a의 기존 이름을 관찰한다.
    // 복사 시 별도 Impl을 생성한다는 근거는 복사 생성자의 make_unique 코드다.
    // Rename 자체도 후보 Impl로 교체하므로 이 결과만으로 포인터 분리를 증명하지 않는다.
    c.Expect(a.Name() == "old" && b.Name() == "new", "deep pimpl copy");

    // std::move 자체는 변환이다. 여기서는 선택된 이동 생성자가 소유권을 옮긴다.
    Settings moved = std::move(a);
    // 2. 이동 원본의 Empty와 대상의 이름을 함께 확인한다.
    c.Expect(a.Empty() && moved.Name() == "old", "move contract");
    // 3. 빈 객체에 Name을 호출하는 계약 위반은 logic_error로 보고한다.
    c.Throws<std::logic_error>([&] { (void)a.Name(); }, "empty contract");

    a.Rename("restored");
    // 4. 이동 후 객체도 새 이름으로 복구할 수 있다.
    c.Expect(a.Name() == "restored", "restore moved-from");
    // std::swap 후보를 열어 두고, 인자 타입과 연관된 비멤버 swap을 ADL로 찾는다.
    using std::swap;
    swap(a,b);
    // 5. 두 객체의 이름이 바뀌었는지 확인한다.
    c.Expect(a.Name() == "new" && b.Name() == "restored", "ADL swap");

    b = moved;
    // 6. 복사 대입의 정상 경로를 확인한다. 자기 대입·이동 대입·빈 원본 복사나
    // 후보 복사 실패를 이 여섯 회에서 각각 실행했다고 해석하지 않는다.
    c.Expect(b.Name() == "old", "assignment");
}); }

#include "check.hpp"
#include <array>
#include <cstddef>
#include <memory>
#include <memory_resource>
#include <new>
#include <vector>

// 이름은 Pool이지만 블록 재사용이나 자체 arena를 구현한 일반 목적 풀은 아니다.
// 전역 할당·해제 호출에 카운터를 붙여 두 정리 경로를 관찰하는 최소 예제다.
// 일반 operator new(bytes)를 사용하므로 확장 정렬 타입을 위한 별도 계약은 없다.
struct Pool {
    int allocated{}, freed{};
    void* Allocate(std::size_t bytes) {
        // 할당이 먼저 성공해야 allocated가 증가한다. 실제 메모리 고갈을 유도하지 않는다.
        void* p = ::operator new(bytes);
        ++allocated;
        return p;
    }
    void Free(void* p) noexcept {
        if (p) {
            ++freed;
            ::operator delete(p);
        }
    }
};

struct Widget {
    Pool* pool;
    explicit Widget(Pool& source, bool fail) : pool(&source) {
        // 저장소 할당 뒤 생성자 본문에서 의도적으로 예외를 던진다.
        // 완성되지 않은 Widget의 소멸자는 호출되지 않는다.
        if (fail) throw std::runtime_error("construction");
    }
    // new(pool) 표현식의 추가 인자 Pool&를 받는 사용자 정의 할당 함수다.
    static void* operator new(std::size_t bytes, Pool& source) { return source.Allocate(bytes); }
    // 생성자가 던지면 new 표현식이 추가 인자 형식이 맞는 이 delete를 찾아 호출한다.
    // 정상 생성된 객체의 수명이 끝날 때 자동으로 이 함수가 선택되는 것은 아니다.
    static void operator delete(void* p, Pool& source) noexcept { source.Free(p); }
};

struct ReturnToPool {
    // deleter는 Pool을 소유하지 않는다. owner보다 Pool이 오래 살아 있어야 한다.
    Pool* pool;
    void operator()(Widget* p) const noexcept {
        if (p) {
            // 정상 생성 경로에서는 객체 수명을 먼저 끝낸 뒤 같은 저장소를 반환한다.
            // destroy_at은 객체 소멸이고 Free는 저장소 해제로 서로 다른 단계다.
            std::destroy_at(p);
            pool->Free(p);
        }
    }
};

int main() { return Run("allocation", [](Checks& c) {
    Pool pool;
    // 검사 1·2: 예외의 종류와 matching placement delete에 의한 반환을 따로 확인한다.
    c.Throws<std::runtime_error>([&] { (void)new(pool) Widget(pool, true); }, "placement ctor failure");
    c.Expect(pool.allocated == 1 && pool.freed == 1, "matching placement delete");
    {
        // 정상 객체에는 사용자 정의 deleter를 가진 unique_ptr를 연결한다.
        // Pool과 deleter의 Pool*가 같은 대상임은 이 구성 코드가 유지하는 전제다.
        std::unique_ptr<Widget, ReturnToPool> owner(new(pool) Widget(pool, false), ReturnToPool{&pool});
        c.Expect(pool.allocated == 2 && pool.freed == 1, "live custom allocation");
    }
    c.Expect(pool.allocated == 2 && pool.freed == 2, "custom deleter on success");

    // 이번에는 이미 있는 자동 저장소에 int를 생성한다. 전역 비할당 placement new다.
    // int의 크기와 정렬을 모두 갖춘 저장소를 제공하며 새 힙 할당을 요청하지 않는다.
    alignas(int) std::array<std::byte, sizeof(int)> bytes{};
    int* value = ::new(static_cast<void*>(bytes.data())) int(42);
    c.Expect(*value == 42, "nonallocating placement new");
    std::destroy_at(value);
    // value를 delete하면 안 된다. bytes가 이 자동 저장소를 제공하며 블록 끝에 정리된다.
    // int의 수명을 끝내는 것과 bytes의 저장소를 해제하는 것은 같은 작업이 아니다.

    // arena → resource → vector 순으로 선언·구성하여 역순 정리가 안전하게 이뤄진다.
    // 고정 버퍼를 기본 정렬로 준비하고 상위 자원은 null_memory_resource로 제한한다.
    // vector<int>의 요청을 관찰하는 예이며 임의의 확장 정렬을 시험하지 않는다.
    alignas(std::max_align_t) std::array<std::byte, 1024> arena{};
    std::pmr::monotonic_buffer_resource resource(arena.data(), arena.size(), std::pmr::null_memory_resource());
    {
        std::pmr::vector<int> values(&resource);
        // reserve(8)은 원소 여덟 개를 담을 용량을 요청한다. 버퍼의 정확한 소비 바이트나
        // 라이브러리 내부 성장 정책을 이 소스에서 측정하지는 않는다.
        values.reserve(8);
        values.push_back(7);
        c.Expect(values[0] == 7, "explicit pmr resource");
    }
    // monotonic 자원은 개별 deallocate로 사용 구간을 재사용하지 않는다.
    // 4096바이트는 처음부터 1024바이트 arena보다 크다. 따라서 이 실패는
    // vector가 얼마나 소비했는지와 무관한 고정 요청이며 실제 시스템 OOM이 아니다.
    c.Throws<std::bad_alloc>([&] { (void)resource.allocate(4096); }, "bounded deterministic failure");
}); }
